cd /home/user && python3 -c "
import openpyxl, datetime
wb=openpyxl.load_workbook('Calendar_Highlight_Weekend_Days.xlsx')
ws=wb.active
print('dims', ws.dimensions, 'max', ws.max_row, ws.max_column)
print('merged', ws.merged_cells.ranges)
print('col widths', {k:v.width for k,v in ws.column_dimensions.items()})
wk=[]
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for c in row:
        if c.value is not None and isinstance(c.value, datetime.datetime):
            if c.value.weekday()>=5: wk.append(c.coordinate)
        f=c.fill
        if f is not None and f.fill_type: print('fill', c.coordinate, f.fill_type, f.fgColor.rgb, f.fgColor.theme)
print('weekend cells', len(wk)); print(' '.join(wk))
"

